loop_default_sleep :: proc(ms: int) {
	time.sleep(time.Duration(ms) * time.Millisecond)
}

// 分片睡眠，返回 false 表示中途被取消。sleep_fn 只是测试注入点，切片逻辑
// 仍在引擎里，保证默认实现和测试替身都尊重取消。
loop_sleep_cancellable :: proc(l: ^Loop, ms: int) -> bool {
	remaining := ms
	for remaining > 0 {
		if platform.cancel_token_cancelled(l.cancel) {
			return false
		}
		slice := min(remaining, RETRY_SLEEP_SLICE_MS)
		l.sleep_fn(slice)
		remaining -= slice
	}
	return !platform.cancel_token_cancelled(l.cancel)
}

// turn_end 覆盖一轮的量；handoff 与 session_title 是独立的一次模型调用
// （manual handoff 没有 turn），都要累加，否则 session_end.usage 会漏掉它们。
historical_usage_from_events :: proc(events: []Event) -> Usage {
	total := Usage{}
	for ev in events {
		switch ev.type {
		case EVENT_TURN_END:
			end: Turn_End_Event
			if json.unmarshal_string(ev.line, &end) == nil {
				total = usage_add(total, end.usage)
			}
		case EVENT_HANDOFF:
			handoff: Handoff_Event
			if json.unmarshal_string(ev.line, &handoff) == nil {
				if usage, has_usage := handoff.usage.?; has_usage {
					total = usage_add(total, usage)
				}
			}
		case EVENT_SESSION_TITLE:
			title: Session_Title_Event
			if json.unmarshal_string(ev.line, &title) == nil {
				if usage, has_usage := title.usage.?; has_usage {
					total = usage_add(total, usage)
				}
			}
		}
	}
	return total
}

next_turn_from_events :: proc(events: []Event) -> int {
	max_turn := 0
	for ev in events {
		if ev.type != EVENT_TURN_START {
			continue
		}
		start: Turn_Start_Event
		if json.unmarshal_string(ev.line, &start) == nil && start.turn > max_turn {
			max_turn = start.turn
		}
	}
	return max_turn + 1
}

loop_init :: proc(
	project: Project,
	settings: ^Settings,
	store: ^Transcript_Store,
	registry: tool.Registry,
	active_tools: []string,
	model, agent_name, session_id: string,
	agent_depth, max_steps, max_tokens: int,
	cancel: ^platform.Cancel_Token,
	events: []Event,
	emitter: Emitter,
) -> Loop {
	// 父 session 是冻结在 session_start 里的信息，loop 直接从事件恢复，
	// 避免把已经在 transcript 中的字段再从 Session 传一遍。
	parent_session_id: Maybe(string)
	if start, found := last_session_start(events); found {
		parent_session_id = start.parent_session_id
	}
	loop := Loop {
		project = project,
		settings = settings,
		store = store,
		provider = provider_init(settings),
		provider_call = provider_stream,
		sleep_fn = loop_default_sleep,
		registry = registry,
		active_tools = active_tools,
		model = model,
		agent_name = agent_name,
		session_id = session_id,
		parent_session_id = parent_session_id,
		agent_depth = agent_depth,
		max_steps = max_steps,
		max_tokens = max_tokens,
		cancel = cancel,
		emitter = emitter,
		historical_usage = historical_usage_from_events(events),
		turn = next_turn_from_events(events),
		calibration_percent = 100,
		// 子代理的职责是回一个结论，不是开新 session。
		handoff_enabled = agent_depth == 0,
	}
	loop.events = make([dynamic]Event, len(events), len(events) + 16)
	copy(loop.events[:], events)
	loop.initial_event_count = len(events)
	loop.attempt_text = make([dynamic]byte, 0, 256)
	return loop
}

loop_destroy :: proc(l: ^Loop) {
	// l.events 的前 len(initial_events) 项由调用方（session.events）持有，
	// 只释放本 loop 追加的那部分行。type 永远是静态字面量，不释放。
	for i in l.initial_event_count ..< len(l.events) {
		delete(l.events[i].line)
	}
	delete(l.events)
	delete(l.attempt_text)
	delete(l.last_text)
	loop_release_owned(l)
}

loop_release_owned :: proc(l: ^Loop) {
	delete(l.owned_message_id)
	l.owned_message_id = ""
	for call in l.owned_calls {
		delete(call.id)
		delete(call.name)
		// input 树由 provider 的 json.parse_string 用 context.allocator 建出来，
		// 全仓只有这里负责回收。
		json.destroy_value(call.input)
	}
	delete(l.owned_calls)
	l.owned_calls = nil
}

