Tool_Slot :: struct {
	index:   int,
	id:      string,
	name:    string,
	args:    [dynamic]byte,
	started: bool,
}

Stream_Assembler :: struct {
	sink:           Stream_Sink,
	fallback_model: string,
	started:        bool,
	finished:       bool,
	failed:         bool,
	message_id:     string,
	model:          string,
	finish_reason:  Maybe(string),
	usage:          Usage,
	text:           [dynamic]byte,
	reasoning:      [dynamic]byte,
	slots:          [dynamic]Tool_Slot,
	last_error:     Provider_Error,
	// 从 chunk 拷出来的 message_id / model / finish_reason / slot.id / slot.name
	// 都放在这里。它们随组装器一起释放，避免逐字段追踪所有权。
	owned:          virtual.Arena,
	owned_alloc:    runtime.Allocator,
	owns_strings:   bool,
}

assembler_init :: proc(a: ^Stream_Assembler, sink: Stream_Sink, model: string) {
	a.sink = sink
	a.fallback_model = model
	a.text = make([dynamic]byte, 0, 256)
	a.reasoning = make([dynamic]byte, 0, 256)
	a.slots = make([dynamic]Tool_Slot, 0, 2)
	a.owns_strings = virtual.arena_init_growing(&a.owned) == nil
	if a.owns_strings {
		a.owned_alloc = virtual.arena_allocator(&a.owned)
	}
}

assembler_destroy :: proc(a: ^Stream_Assembler) {
	delete(a.text)
	delete(a.reasoning)
	for &slot in a.slots {
		delete(slot.args)
	}
	delete(a.slots)
	if a.owns_strings {
		virtual.arena_destroy(&a.owned)
	}
}

// chunk 解析出的字符串在本轮结束后会被释放，需要留存的字段必须拷一份。
// 统一放进 owned arena，省掉逐字段的所有权标记。
assembler_own :: proc(a: ^Stream_Assembler, value: string) -> string {
	if !a.owns_strings || len(value) == 0 {
		return value
	}
	cloned, cerr := strings.clone(value, a.owned_alloc)
	if cerr != nil {
		return value
	}
	return cloned
}

assembler_fail :: proc(a: ^Stream_Assembler, err: Provider_Error) -> Provider_Error {
	if a.failed {
		return err
	}
	a.failed = true
	a.last_error = err
	emit_provider_event(a.sink, Provider_Error_Event{err = err})
	return err
}

assembler_slot :: proc(a: ^Stream_Assembler, index: int) -> ^Tool_Slot {
	for &slot in a.slots {
		if slot.index == index {
			return &slot
		}
	}
	slot := Tool_Slot{index = index}
	slot.args = make([dynamic]byte, 0, 64)
	append(&a.slots, slot)
	return &a.slots[len(a.slots) - 1]
}

